BEGIN;

-- Renombra las fichas individuales de Luny Tunes a sus nombres reales: Francisco Saldaña
-- (antes «Luny») y Víctor Cabrera (antes «Tunes»); el dúo sigue llamándose «Luny Tunes».
-- Reescribe ambas biografías con material nuevo (ensegundos.do, Wikipedia, Reggaeton de
-- Duke UP, Discogs) y corrige el displayText de las referencias que apuntan a ellos desde
-- la ficha ya publicada de Luny Tunes, para no dejar enlaces con el nombre viejo.

UPDATE artists SET name = 'Francisco Saldaña', sort_name = 'Saldaña, Francisco', aliases = ARRAY['Luny', 'Luny Tunes']::text[],
       birth_place = 'San Pedro de Macorís', province = 'San Pedro de Macorís' WHERE slug = 'luny';

UPDATE artists SET name = 'Víctor Cabrera', sort_name = 'Cabrera, Víctor', aliases = ARRAY['Tunes', 'Luny Tunes']::text[],
       birth_place = 'Higüey', province = 'La Altagracia' WHERE slug = 'tunes';

